WITH inserted AS (INSERT INTO zc_private.discord_worker_state(key,cursor_event_id) VALUES($1,(SELECT COALESCE(MAX(id),0) FROM public.discord_activity_event)) ON CONFLICT(key) DO NOTHING RETURNING *), row AS (SELECT * FROM inserted UNION ALL SELECT * FROM zc_private.discord_worker_state WHERE key=$1 LIMIT 1) SELECT jsonb_build_object( 'key',key,'cursorEventId',cursor_event_id::text,'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS value FROM row
